 function visibleControl(c,p=experiment().inputs){const id=activity().id;if(id==='turning'&&['left','right','effort','reach','angle'].includes(c.key))return p.mode==='wrench'?['effort','reach','angle'].includes(c.key):['left','right'].includes(c.key);if(id==='torque'&&['left','right','effort','arm','loadArm'].includes(c.key))return p.mode==='beam'?['effort','arm','loadArm'].includes(c.key):['left','right'].includes(c.key);if(id==='push'&&c.key==='mass'&&p.objectType!=='cart')return false;if(id==='scale'&&c.key==='grams')return p.object==='custom';if(id==='elastic'&&c.key==='mass')return p.springMode==='hanging';if(id==='elastic'&&c.key==='springMode')return false;if(id==='elastic'&&c.key==='extension')return p.springMode==='stretch';if(['diver-intro','floating','review-middle'].includes(id)&&['volume','clips','fill'].includes(c.key))return c.key===({diver:'volume',balloon:'clips',submarine:'fill'}[p.case]);if(id==='shelf'&&c.key==='length')return false;return true;}
